import{_ as a,o as n,c as t,a3 as l}from"./chunks/framework.MGD2uYU7.js";const g=JSON.parse('{"title":"SC-09 — Đăng nhập","description":"","frontmatter":{"title":"SC-09 — Đăng nhập"},"headers":[],"relativePath":"wireframes/auth/sc-09-dang-nhap.md","filePath":"wireframes/auth/sc-09-dang-nhap.md","lastUpdated":null}'),i={name:"wireframes/auth/sc-09-dang-nhap.md"};function c(e,s,p,o,h,d){return n(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-09-—-đang-nhap" tabindex="-1">SC-09 — Đăng nhập <a class="header-anchor" href="#sc-09-—-đang-nhap" aria-label="Permalink to &quot;SC-09 — Đăng nhập&quot;">​</a></h1><p><span class="wf-badge info">Route: /dang-nhap</span> <span class="wf-badge muted">Nguồn: docs/05 §3 · docs/03 UC-01 · docs/08 BR-IDT · docs/06 §5</span></p><p><strong>Ai xem màn này</strong>: Khách bấm hành động cần tài khoản (đặt lịch xem, đăng ký đấu giá…) bị chuyển vào kèm deep-link intent · Thành viên hết phiên (silent refresh thất bại) · User vừa được CS đặt lại mật khẩu (đăng nhập lần đầu bằng mật khẩu tạm). <strong>Mục đích / cảm xúc thiết kế</strong>: nhanh — an toàn — không dọa nạt. Đăng nhập là &quot;cửa&quot; không phải đích đến: tối thiểu trường nhập, lỗi theo chuẩn một nguồn docs/06 §5, KHÔNG tiết lộ email có tồn tại hay không (chống dò tài khoản), và luôn có lối thoát con người khi kẹt (CSKH 1900-xxx — v1 không có self-reset). <strong>Ví dụ số dùng trong bản vẽ</strong>: tài khoản <code>demo@example.com</code> — Nguyễn Văn Demo; user vừa bấm &quot;Đặt lịch xem&quot; ở trang chi tiết tin căn <code>CT2-A18.05</code> — dự án NOXH <code>HP-380</code> (deep-link return); hotline <code>1900-xxx</code>.</p><h2 id="_1-desktop-—-form-trang-thai-binh-thuong-kem-deep-link-return" tabindex="-1">1. Desktop — form trạng thái bình thường (kèm deep-link return) <a class="header-anchor" href="#_1-desktop-—-form-trang-thai-binh-thuong-kem-deep-link-return" aria-label="Permalink to &quot;1. Desktop — form trạng thái bình thường (kèm deep-link return)&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/dang-nhap?next=/nha-o-xa-hoi/lst_01JZK3M9W2Q8</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-btn sm">Đăng ký</span></span></div><div class="wf-container"><div class="wf-col" style="max-width:440px;margin:24px auto;gap:12px;"><div class="wf-toast info">Bạn cần đăng nhập để tiếp tục đặt lịch xem căn <b>CT2-A18.05</b> — sau khi đăng nhập sẽ tự quay lại trang bạn đang xem <span class="wf-callout">1</span></div><div class="wf-card"><div class="pad wf-col" style="gap:14px;"><div class="wf-col" style="gap:2px;"><span class="wf-title lg">Đăng nhập</span><span class="wf-small">Chào mừng trở lại sàn NOXH AnPhucRealEstate</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email <span class="wf-danger-text">*</span></span><div class="wf-input filled"><span>demo@example.com</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><div class="wf-row between" style="gap:8px;"><span class="wf-small wf-strong">Mật khẩu <span class="wf-danger-text">*</span></span><span class="wf-small wf-accent"><b>Quên mật khẩu?</b> <span class="wf-callout">2</span></span></div><div class="wf-input filled"><span>••••••••••••</span><span class="caret">👁 <span class="wf-callout">3</span></span></div></div><span class="wf-btn primary lg block">Đăng nhập <span class="wf-callout" style="background:#fff;color:var(--wf-accent);">4</span></span><div class="wf-center"><span class="wf-small">Chưa có tài khoản? <b class="wf-accent">Đăng ký miễn phí</b> → SC-10</span></div></div></div><span class="wf-small wf-center">CSKH 1900-xxx · Quy chế hoạt động · Chính sách bảo mật</span></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-09 · docs/03 UC-01 · docs/08 BR-IDT)</div><ol><li><span class="num">1</span><span><b>Deep-link return</b>: query <code>?next=</code> lưu đúng trang user đang xem trước khi bị chặn (guard 401). Đăng nhập thành công → quay lại <code>next</code>; không có <code>next</code> → về <code>/dashboard</code> (SC-20). Banner xanh chỉ hiện khi có <code>next</code> — vào trực tiếp thì ẩn. <span class="ref">docs/05 §2</span> <span class="ref">UC-03 AF-1</span></span></li><li><span class="num">2</span><span><b>&quot;Quên mật khẩu?&quot; KHÔNG dẫn tới form reset</b> — v1 không có self-service reset. Link mở popover hướng dẫn gọi CSKH (vẽ ở mục 2). Designer không thiết kế màn &quot;nhập email lấy lại mật khẩu&quot; cho v1. <span class="ref">UC-01 AF-3</span> <span class="ref">BR-ADM-04</span> <span class="ref">FR-IDT-07</span></span></li><li><span class="num">3</span><span>Show/hide mật khẩu: icon mắt, mặc định ẩn; click toggle không mất focus ô nhập. 👁 trong wireframe là placeholder vị trí — thay icon thật. <span class="ref">docs/05 §1.7</span></span></li><li><span class="num">4</span><span><b>Submit</b>: <code>POST /auth/login</code> → nút chuyển loading + disabled (chống double-submit); thành công → phát access 15 phút + refresh 7 ngày (rotation) rồi redirect theo callout 1. Validate onBlur + onSubmit, message tại field, string một nguồn docs/06 §5. Phím Enter = bấm nút. <span class="ref">docs/05 §1.3/§1.5</span> <span class="ref">FR-IDT-02</span> <span class="ref">BR-IDT-03</span></span></li></ol></div><h2 id="_2-desktop-—-popover-quen-mat-khau-huong-dan-qua-cs-uc-01-af-3" tabindex="-1">2. Desktop — popover &quot;Quên mật khẩu?&quot; (hướng dẫn qua CS, UC-01 AF-3) <a class="header-anchor" href="#_2-desktop-—-popover-quen-mat-khau-huong-dan-qua-cs-uc-01-af-3" aria-label="Permalink to &quot;2. Desktop — popover &quot;Quên mật khẩu?&quot; (hướng dẫn qua CS, UC-01 AF-3)&quot;">​</a></h2><div class="wf"><div class="wf-modal-overlay"><div class="wf-modal"><div class="head">Quên mật khẩu? <span class="wf-callout">5</span></div><div class="wf-text">Hiện tại AnPhucRealEstate <b>chưa hỗ trợ tự lấy lại mật khẩu</b>. Bộ phận CSKH sẽ đặt lại mật khẩu giúp bạn sau khi xác minh danh tính:</div><div class="wf-col" style="margin:10px 0;gap:8px;"><div class="wf-col" style="gap:8px;"><div class="wf-row" style="gap:8px;"><span class="wf-badge info">1</span><span class="wf-text">Gọi hotline <b>CSKH 1900-xxx</b> (08:00–20:00 hằng ngày)</span></div><div class="wf-row" style="gap:8px;"><span class="wf-badge info">2</span><span class="wf-text">Xác minh danh tính: họ tên + số CCCD + email/SĐT đã đăng ký</span></div><div class="wf-row" style="gap:8px;"><span class="wf-badge info">3</span><span class="wf-text">Mật khẩu tạm (1 lần dùng) được gửi tới email <b>demo@example.com</b> của bạn</span></div><div class="wf-row" style="gap:8px;"><span class="wf-badge info">4</span><span class="wf-text">Đăng nhập bằng mật khẩu tạm → hệ thống <b>bắt buộc đổi mật khẩu mới</b> trước khi tiếp tục <span class="wf-callout">6</span></span></div></div></div><div class="wf-note">CSKH <b>không bao giờ</b> hỏi mật khẩu hiện tại hay mã OTP của bạn qua điện thoại. Mọi phiên đăng nhập cũ sẽ bị đăng xuất khi đặt lại mật khẩu.</div><span class="wf-btn primary block">Đã hiểu</span><span class="wf-btn ghost block" style="margin-top:8px;">Gọi 1900-xxx</span></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">5</span><span>Popover đóng bằng nút &quot;Đã hiểu&quot;, phím Esc hoặc click ra ngoài — không phải modal chặn. Copy nêu <b>đúng 4 bước thật của flow ADMIN reset</b> (endpoint 63 <code>POST /admin/users/{id}/reset-password</code>, reason bắt buộc, thu hồi toàn bộ refresh token, audit <code>USER_RESET_PASSWORD</code>) để user không chờ email reset không tồn tại. <span class="ref">UC-01 AF-3/AF-4</span> <span class="ref">BR-ADM-04</span> <span class="ref">docs/06 §4.8b</span></span></li><li><span class="num">6</span><span><b>Gate đổi mật khẩu bắt buộc</b>: đăng nhập bằng mật khẩu tạm trả <code>passwordMustChange: true</code> — message chuẩn: &quot;Tài khoản vừa được đặt lại mật khẩu — vui lòng đổi mật khẩu trước khi tiếp tục&quot;; FE redirect thẳng màn đổi mật khẩu (SC-29), mọi API khác trả 403 <code>AUTH_PASSWORD_MUST_CHANGE</code> tới khi đổi xong. <span class="ref">docs/06 §5</span> <span class="ref">FR-IDT-07</span></span></li></ol></div><h2 id="_3-desktop-—-trang-thai-loi-bien-bat-buoc-thiet-ke-đu" tabindex="-1">3. Desktop — trạng thái lỗi &amp; biên (bắt buộc thiết kế đủ) <a class="header-anchor" href="#_3-desktop-—-trang-thai-loi-bien-bat-buoc-thiet-ke-đu" aria-label="Permalink to &quot;3. Desktop — trạng thái lỗi &amp; biên (bắt buộc thiết kế đủ)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: 401 — SAI EMAIL/MẬT KHẨP</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast danger">Email hoặc mật khẩu không đúng <span class="wf-callout danger">7</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email</span><div class="wf-input filled error"><span>demo@example.com</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Mật khẩu</span><div class="wf-input filled error"><span>••••••••</span><span class="caret">👁</span></div></div><span class="wf-btn primary block">Đăng nhập</span><span class="wf-small">Nhập sai 4/5 lần trong 15 phút — sau lần thứ 5 tài khoản tạm khóa theo IP (xem ô bên phải). Dữ liệu đã nhập được giữ nguyên, focus về ô email.</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: 429 — RATE LIMIT (5 LẦN SAI / 15 PHÚT / IP)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast warn">Quá nhiều lần đăng nhập thất bại — tạm khóa 15 phút <span class="wf-callout warn">8</span></div><div class="wf-center wf-col" style="gap:4px;"><span class="wf-small">THỬ LẠI SAU</span><br><span class="wf-countdown">14 : 32</span><span class="wf-small">đếm ngược mm:ss</span></div><span class="wf-btn disabled block">Đăng nhập (tạm khóa)</span><span class="wf-small">Toàn bộ form disabled tới khi đồng hồ về 00:00 thì tự mở lại — không cần reload. Quên mật khẩu trong lúc bị khóa? Gọi CSKH 1900-xxx.</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: TÀI KHOẢN BỊ TẠM NGƯNG (SAU KHI ĐĂNG NHẬP)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast danger">Tài khoản của bạn đã bị tạm ngưng hoạt động — liên hệ CSKH 1900-xxx để được giải thích lý do <span class="wf-callout danger">9</span></div><span class="wf-small">Đăng nhập vẫn thành công; banner đỏ này hiện sticky trên mọi màn /(user). User SUSPENDED bị chặn 403 <code>USER_SUSPENDED</code> ở mọi thao tác nghiệp vụ (đăng tin, đấu giá, đặt lịch); vẫn đọc được trang public.</span><span class="wf-btn block">Xem trang chủ (read-only)</span></div></div></div><div class="wf-col"><span class="wf-state-label">TRẠNG THÁI: PHIÊN HẾT HẠN (REFRESH THẤT BẠI)</span><div class="wf-card"><div class="pad wf-col" style="gap:10px;"><div class="wf-toast warn">Phiên đăng nhập đã hết hạn — vui lòng đăng nhập lại <span class="wf-callout warn">10</span></div><span class="wf-small">Xảy ra khi silent refresh thất bại hoặc phát hiện refresh token bị tái sử dụng (hệ thống thu hồi toàn bộ token family vì lý do bảo mật). URL giữ kèm <code>?next=</code> để đăng nhập xong quay lại đúng trang đang xem.</span><span class="wf-btn primary block">Đăng nhập lại</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích lỗi &amp; biên</div><ol><li><span class="num">7</span><span><b>Message gộp, không chỉ đích danh trường sai</b>: &quot;Email hoặc mật khẩu không đúng&quot; — nguyên văn docs/06 §5 (<code>AUTH_INVALID_CREDENTIALS</code>). Không hiện &quot;email chưa đăng ký&quot; hay &quot;mật khẩu sai&quot; (chống dò tài khoản). Highlight đỏ cả 2 ô. <span class="ref">FR-IDT-02</span> <span class="ref">docs/06 §5</span></span></li><li><span class="num">8</span><span><b>429 <code>RATE_LIMITED</code></b>: 5 lần sai/15 phút/IP → khóa form + <code>wf-countdown</code> mm:ss tính theo thời gian server (header <code>X-Server-Time</code>/Retry-After — không tin đồng hồ máy khách, cùng nguyên tắc countdown SC-06). <span class="ref">UC-01 EF-3</span> <span class="ref">NFR-S-02</span></span></li><li><span class="num">9</span><span>SUSPENDED: login được nhưng mọi mutation nghiệp vụ 403 — UI không chặn tận cửa, thay bằng banner lý do + số CSKH (admin suspend luôn có reason, audit). <span class="ref">BR-IDT-07</span> <span class="ref">BR-IDT-04</span></span></li><li><span class="num">10</span><span>Refresh reuse detection → thu hồi cả family → user phải đăng nhập lại; copy thân thiện, không đổ lỗi user. <span class="ref">UC-01 AF-2/EF-4</span> <span class="ref">BR-IDT-03</span> <span class="ref">NFR-S-01</span></span></li><li><span class="num">11</span><span>Mọi hộp lỗi server (không riêng 4 ô trên) kèm <b>traceId rút gọn</b> để báo CS — component <code>ErrorState(+traceId)</code> dùng chung. <span class="ref">docs/05 §1.4/§6</span></span></li></ol></div><h2 id="_4-mobile-360px-—-form-đang-nhap" tabindex="-1">4. Mobile 360px — form đăng nhập <a class="header-anchor" href="#_4-mobile-360px-—-form-đang-nhap" aria-label="Permalink to &quot;4. Mobile 360px — form đăng nhập&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — FORM BÌNH THƯỜNG</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm">Đăng ký</span></div><div class="wf-container" style="padding:12px;"><div class="wf-toast info">Đăng nhập để tiếp tục đặt lịch xem căn <b>CT2-A18.05</b></div><div class="wf-col" style="gap:12px;margin-top:12px;"><span class="wf-title lg">Đăng nhập</span><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">Email</span><div class="wf-input filled"><span>demo@example.com</span><span class="caret">✎</span></div></div><div class="wf-col" style="gap:4px;"><div class="wf-row between" style="gap:8px;"><span class="wf-small wf-strong">Mật khẩu</span><span class="wf-small wf-accent"><b>Quên?</b></span></div><div class="wf-input filled"><span>••••••••••••</span><span class="caret">👁</span></div></div><span class="wf-btn primary lg block">Đăng nhập</span><div class="wf-center"><span class="wf-small">Chưa có tài khoản? <b class="wf-accent">Đăng ký</b></span></div><span class="wf-small wf-center">CSKH 1900-xxx</span></div></div></div></div><div><span class="wf-state-label">MOBILE — 429 TẠM KHÓA 15 PHÚT</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm">Đăng ký</span></div><div class="wf-container" style="padding:12px;"><div class="wf-col" style="gap:12px;margin-top:12px;"><span class="wf-title lg">Đăng nhập</span><div class="wf-toast warn">Quá nhiều lần đăng nhập thất bại — tạm khóa 15 phút</div><div class="wf-center"><span class="wf-small">THỬ LẠI SAU</span><br><span class="wf-countdown sm">14 : 32</span></div><span class="wf-btn disabled block">Đăng nhập (tạm khóa)</span><span class="wf-small wf-center">Quên mật khẩu? Gọi CSKH 1900-xxx</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Card form bỏ viền trên mobile — form chiếm toàn bộ chiều ngang khung 360px, padding 12px; touch target nút ≥44px; bàn phím hiện loại <code>email</code> cho ô email, <code>password</code> cho ô mật khẩu. &quot;Quên mật khẩu?&quot; vẫn mở cùng popover mục 2 (dạng bottom-sheet trên mobile).</span></li></ol></div><h2 id="_5-checklist-designer-khi-dung-figma-cho-sc-09" tabindex="-1">5. Checklist designer khi dựng Figma cho SC-09 <a class="header-anchor" href="#_5-checklist-designer-khi-dung-figma-cho-sc-09" aria-label="Permalink to &quot;5. Checklist designer khi dựng Figma cho SC-09&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (card giữa trang, max 440px) / mobile 360 / tablet 768 (giữ card giữa)</li><li>[ ] Đủ trạng thái: bình thường (có/không banner deep-link) · loading nút · 401 sai credentials · 429 countdown mm:ss · suspended banner · must-change password gate · phiên hết hạn</li><li>[ ] Popover &quot;Quên mật khẩu?&quot; 4 bước gọi CS — KHÔNG vẽ màn self-reset (v1 không có, UC-01 AF-3)</li><li>[ ] Copy đúng nguyên văn docs/06 §5: &quot;Email hoặc mật khẩu không đúng&quot; · &quot;Tài khoản vừa được đặt lại mật khẩu — vui lòng đổi mật khẩu trước khi tiếp tục&quot;; lỗi kèm traceId rút gọn</li><li>[ ] Không emoji icon trong UI production (👁/🔔 trong wireframe chỉ là placeholder vị trí — thay bằng icon set thật)</li><li>[ ] Accessibility: label cho mọi input, focus ring, contrast AA, thông báo lỗi đọc được bằng screen reader (aria-live), countdown không chỉ dựa vào màu</li><li>[ ] Ngày giờ hiển thị <code>dd/MM/yyyy HH:mm</code> (GMT+7) nếu có; hotline <code>1900-xxx</code> nhất quán footer + popover</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (vd số lần sai trước khi khóa, flow reset) cần PM duyệt trên docs/08 trước.</p></div>',18)])])}const u=a(i,[["render",c]]);export{g as __pageData,u as default};
